def cli_build_order(build_order):
    """
    Text formatter for 'conan graph build-order'.

    The InstallGraph can be serialized in two different shapes depending on the selected
    --order mode:
      - recipe: each item includes a nested 'packages' field with levels of packages
      - configuration: each item is a flat object without 'packages' (single package configuration)

    This formatter must handle both shapes. JSON formatter remains unchanged and dumps raw data.
    """
    # TODO: Very simple cli output, probably needs to be improved
    for level in build_order:
        for item in level:
            packages_levels = item.get('packages')
            if packages_levels is not None:
                # recipe mode: iterate inner package levels
                for package_level in packages_levels:
                    for package in package_level:
                        cli_out_write(f"{item['ref']}:{package['package_id']} - {package['binary']}")
            else:
                # configuration mode: flat item per package configuration
                cli_out_write(f"{item['ref']}:{item['package_id']} - {item['binary']}")

