import sys
from io import StringIO

from conan.cli.commands.graph import cli_build_order


def capture_stdout(func, *args, **kwargs):
    old_stdout = sys.stdout
    try:
        sys.stdout = StringIO()
        func(*args, **kwargs)
        return sys.stdout.getvalue()
    finally:
        sys.stdout = old_stdout


def test_recipe_mode_formatter_handles_packages_levels():
    # Build-order data for recipe mode: items contain 'packages' levels
    build_order = [
        [
            {
                'ref': 'pkg/1.0',
                'packages': [
                    [
                        {'package_id': 'pid1', 'binary': 'Build'},
                        {'package_id': 'pid2', 'binary': 'Cache'},
                    ],
                    [
                        {'package_id': 'pid3', 'binary': 'Build'},
                    ],
                ]
            }
        ]
    ]

    out = capture_stdout(cli_build_order, build_order)
    # Should print one line per package entry
    lines = [l.strip() for l in out.splitlines() if l.strip()]
    assert 'pkg/1.0:pid1 - Build' in lines
    assert 'pkg/1.0:pid2 - Cache' in lines
    assert 'pkg/1.0:pid3 - Build' in lines


def test_configuration_mode_formatter_handles_flat_items():
    # Build-order data for configuration mode: items are flat without 'packages'
    build_order = [
        [
            {'ref': 'pkgA/1.0', 'package_id': 'aid', 'binary': 'Build'},
            {'ref': 'pkgB/1.0', 'package_id': 'bid', 'binary': 'Cache'},
        ]
    ]

    out = capture_stdout(cli_build_order, build_order)
    lines = [l.strip() for l in out.splitlines() if l.strip()]
    # Exactly one line per item
    assert lines == ['pkgA/1.0:aid - Build', 'pkgB/1.0:bid - Cache']
